-- Massa de dados = DUMP LITERAL do estado real do banco journey_admin local
-- (gerado via pg_dump --data-only --column-inserts em 2026-09-01), contendo
-- so a versao que era PUBLICADA de cada jornada no ambiente de origem, renumerada
-- pra version_number=1 e salva como UNPUBLISHED (nao PUBLISHED) de proposito:
-- popular_massa_dados chama o endpoint de REPUBLISH dessa versao (nao o "Publicar"
-- generico), que exige UNPUBLISHED e republica o mesmo version_id/version_number
-- sem criar uma v2 — e a unica forma de version_number=1 continuar sendo a versao
-- publicada depois do script rodar. Cobre produto/canal/jornada/fluxo/versao/
-- publicacao + credenciais de IA/mensageria, na ordem correta de FK.
--
-- Exceção: o valor de ai_provider_credential.api_key foi substituído pelo
-- placeholder 'REPLACE_WITH_REAL_API_KEY' — a chave real da Gemini NÃO é
-- versionada em git. Depois de rodar este script, reconfigure a credencial de
-- IA manualmente pela UI/API se for usar funcionalidades que dependem dela.
--
-- Como rodar: use popular_massa_dados.sh/.bat/.ps1 (checa a stack, zera o Camunda,
-- popula este SQL e republica cada jornada no engine) em vez de rodar este arquivo
-- isolado.
BEGIN;

TRUNCATE TABLE journey_publication, journey_version, flow, journey, channel, product, form, credential_reference, messaging_cluster, ai_provider_credential, audit_event;

